conf:
server {
listen 8080;
server_name _;
root /usr/share/nginx/html;
index index.html;
add_header X-Frame-Options "DENY" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self' ; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
resolver 10.0.0.2 valid=10s ipv6=off;
resolver_timeout 5s;
set $giano_wallet_api http://wallet-api:8080;
location ~ ^/api/(?<giano_api_path>.*)$ {
proxy_pass $giano_wallet_api/$giano_api_path$is_args$args;
proxy_http_version 1.1;
proxy_set_header Host $host;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
}
location = /.well-known/webauthn {
proxy_pass $giano_wallet_api/.well-known/webauthn;
proxy_set_header Host $host;
}
location = /config.json {
add_header Cache-Control "no-store" always;
}
location /assets/ {
add_header Cache-Control "public, max-age=31536000, immutable" always;
}
location / {
try_files $uri $uri/ /index.html;
}
}
